#include "search.h"
#include <ctype.h>
#include <limits.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>

static size_t hash_word(const char *s){uint32_t h=2166136261u;while(*s){h^=(unsigned char)*s++;h*=16777619u;}return (size_t)(h%HS_BUCKETS);}
static char *copy_string(const char *s){size_t n=strlen(s)+1;char *p=malloc(n);if(p)memcpy(p,s,n);return p;}
static Term *find_term(SearchIndex *idx,const char *word,int create){size_t b=hash_word(word);Term *t=idx->buckets[b];while(t){if(strcmp(t->word,word)==0)return t;t=t->next;}if(!create)return NULL;t=calloc(1,sizeof(*t));if(!t)return NULL;t->word=copy_string(word);if(!t->word){free(t);return NULL;}t->next=idx->buckets[b];idx->buckets[b]=t;idx->unique_terms++;return t;}
static int add_posting(Term *t,uint32_t id){for(size_t i=0;i<t->count;i++)if(t->postings[i].doc_id==id){if(t->postings[i].frequency==UINT32_MAX)return -1;t->postings[i].frequency++;return 0;}if(t->count==t->capacity){size_t cap=t->capacity?t->capacity*2:4;if(cap<t->capacity||cap>SIZE_MAX/sizeof(Posting))return -1;Posting *p=realloc(t->postings,cap*sizeof(*p));if(!p)return -1;t->postings=p;t->capacity=cap;}t->postings[t->count++]=(Posting){id,1};return 0;}
static void remove_postings(SearchIndex *idx,uint32_t id){for(size_t b=0;b<HS_BUCKETS;b++){Term **pp=&idx->buckets[b];while(*pp){Term *t=*pp;size_t w=0;for(size_t i=0;i<t->count;i++)if(t->postings[i].doc_id!=id)t->postings[w++]=t->postings[i];t->count=w;if(!w){*pp=t->next;free(t->postings);free(t->word);free(t);idx->unique_terms--;}else pp=&t->next;}}}
int hs_supported_file(const char *path){if(!path)return 0;const char *dot=strrchr(path,'.');if(!dot)return 0;const char *exts[]={".txt",".md",".c",".h",".cpp",".hpp",".cc",".py",".java",".js",".ts",".json",".xml",".html",".css",".csv",".log",".sql",".sh",".go",".rs"};for(size_t i=0;i<sizeof(exts)/sizeof(exts[0]);i++){const char *a=dot,*b=exts[i];while(*a&&*b&&tolower((unsigned char)*a)==*b){a++;b++;}if(!*a&&!*b)return 1;}return 0;}
int hs_init(SearchIndex *idx){if(!idx)return -1;memset(idx,0,sizeof(*idx));idx->buckets=calloc(HS_BUCKETS,sizeof(Term*));idx->next_id=1;return idx->buckets?0:-1;}
void hs_destroy(SearchIndex *idx){if(!idx)return;if(idx->buckets){for(size_t b=0;b<HS_BUCKETS;b++){Term *t=idx->buckets[b];while(t){Term *next=t->next;free(t->word);free(t->postings);free(t);t=next;}}free(idx->buckets);}free(idx->docs);memset(idx,0,sizeof(*idx));}
const Document *hs_document(const SearchIndex *idx,uint32_t id){if(!idx)return NULL;for(size_t i=0;i<idx->count;i++)if(idx->docs[i].id==id&&idx->docs[i].active)return &idx->docs[i];return NULL;}
static Document *mutable_document(SearchIndex *idx,uint32_t id){return (Document *)hs_document(idx,id);}
size_t hs_active_documents(const SearchIndex *idx){size_t n=0;if(idx)for(size_t i=0;i<idx->count;i++)if(idx->docs[i].active)n++;return n;}
static int index_file(SearchIndex *idx,Document *d){struct stat st;if(stat(d->path,&st)!=0||!S_ISREG(st.st_mode)||st.st_size<0||(uint64_t)st.st_size>HS_MAX_FILE)return -1;FILE *f=fopen(d->path,"rb");if(!f)return -1;char word[HS_WORD_MAX];size_t n=0;int c,error=0;uint32_t words=0;while((c=fgetc(f))!=EOF){if(isalnum((unsigned char)c)||c=='_'){if(n<sizeof(word)-1)word[n++]=(char)tolower((unsigned char)c);}else if(n){word[n]=0;Term *t=find_term(idx,word,1);if(!t||add_posting(t,d->id)!=0||words==UINT32_MAX){error=1;break;}words++;n=0;}}if(!error&&n){word[n]=0;Term *t=find_term(idx,word,1);if(!t||add_posting(t,d->id)!=0||words==UINT32_MAX)error=1;else words++;}if(ferror(f))error=1;if(fclose(f)!=0)error=1;if(error){remove_postings(idx,d->id);return -1;}d->size=(uint64_t)st.st_size;d->words=words;return 0;}
int hs_add(SearchIndex *idx,const char *path){if(!idx||!idx->buckets||!path)return -1;size_t len=strlen(path);if(!len||len>=HS_PATH_MAX||!hs_supported_file(path)||idx->next_id==UINT32_MAX||idx->next_id>INT_MAX)return -1;for(size_t i=0;i<idx->count;i++)if(idx->docs[i].active&&strcmp(idx->docs[i].path,path)==0)return -2;if(idx->count==idx->capacity){size_t cap=idx->capacity?idx->capacity*2:16;if(cap<idx->capacity||cap>SIZE_MAX/sizeof(Document))return -1;Document *p=realloc(idx->docs,cap*sizeof(*p));if(!p)return -1;idx->docs=p;idx->capacity=cap;}Document *d=&idx->docs[idx->count];memset(d,0,sizeof(*d));d->id=idx->next_id;memcpy(d->path,path,len+1);d->active=1;if(index_file(idx,d)!=0)return -1;idx->next_id++;idx->count++;return (int)d->id;}
int hs_update(SearchIndex *idx,uint32_t id){if(!idx||!idx->buckets)return -1;Document *d=mutable_document(idx,id);if(!d)return -1;/* Stage file readability before replacing existing postings. */struct stat st;if(stat(d->path,&st)!=0||!S_ISREG(st.st_mode)||st.st_size<0||(uint64_t)st.st_size>HS_MAX_FILE)return -1;FILE *f=fopen(d->path,"rb");if(!f)return -1;fclose(f);remove_postings(idx,id);return index_file(idx,d);}
int hs_delete(SearchIndex *idx,uint32_t id){if(!idx||!idx->buckets)return -1;Document *d=mutable_document(idx,id);if(!d)return -1;remove_postings(idx,id);d->active=0;return 0;}
static int compare_results(const void *a,const void *b){const SearchResult *x=a,*y=b;if(x->score>y->score)return -1;if(x->score<y->score)return 1;return (x->doc_id>y->doc_id)-(x->doc_id<y->doc_id);}
size_t hs_search(SearchIndex *idx,const char *query,SearchResult **out){if(out)*out=NULL;if(!idx||!idx->buckets||!query||!out)return 0;clock_t start=clock();char terms[32][HS_WORD_MAX],word[HS_WORD_MAX];size_t nt=0,n=0;for(const unsigned char *p=(const unsigned char *)query;;p++){int c=*p;if(isalnum(c)||c=='_'){if(n<HS_WORD_MAX-1)word[n++]=(char)tolower(c);}else if(n){word[n]=0;int seen=0;for(size_t j=0;j<nt;j++)if(strcmp(terms[j],word)==0)seen=1;if(!seen&&nt<32)strcpy(terms[nt++],word);n=0;}if(!c)break;}
size_t active=hs_active_documents(idx);SearchResult *r=calloc(active?active:1,sizeof(*r));if(!r)return 0;size_t nr=0;/* Only visit posting-list candidates; no full-document scoring scan. */for(size_t j=0;j<nt;j++){Term *t=find_term(idx,terms[j],0);if(!t)continue;double idf=log(((double)active+1)/((double)t->count+1))+1;for(size_t k=0;k<t->count;k++){Posting p=t->postings[k];const Document *d=hs_document(idx,p.doc_id);if(!d)continue;idx->candidate_visits++;double score=((double)p.frequency/(d->words?d->words:1))*idf;size_t z=0;while(z<nr&&r[z].doc_id!=p.doc_id)z++;if(z==nr){r[nr++]=(SearchResult){p.doc_id,score};}else r[z].score+=score;}}qsort(r,nr,sizeof(*r),compare_results);*out=r;idx->searches++;idx->total_ms+=1000.0*(double)(clock()-start)/(double)CLOCKS_PER_SEC;return nr;}
void hs_print_results(const SearchIndex *idx,const SearchResult *r,size_t n,FILE *out){if(!out)return;for(size_t i=0;i<n;i++){const Document *d=hs_document(idx,r[i].doc_id);if(d)fprintf(out,"%zu. [ID %u] %.5f | %s | %llu bytes\n",i+1,d->id,r[i].score,d->path,(unsigned long long)d->size);}if(!n)fprintf(out,"No matching documents.\n");}
